<script setup>
import {ref,onBeforeUnmount,computed,watch,shallowRef} from 'vue';
import {nativeViewerZip,NATIVE_VIEWER_PROFILE,nativeViewerCapabilities} from '../shared/native-viewer-adapter.mjs';
import {nativeResourceCheck,NATIVE_RESOURCE_DEFAULTS,traceNativeTriangle} from '../shared/native-resource-budget.mjs';
import {MAX_SIMULATION_HANDOFF_BYTES} from '../shared/simulation-handoff.mjs';
let disposed=false;onBeforeUnmount(()=>{disposed=true;});
const purpose=ref('geometry'),required=computed(()=>purpose.value==='physics'?['physicalMaterialExecution','rigidBodySimulation']:['sceneGeometry']),capabilities=computed(()=>nativeViewerCapabilities(required.value));
const maxTriangles=ref(NATIVE_RESOURCE_DEFAULTS.maxTriangles),cpuMiB=ref(64),lastManifest=shallowRef(null),triangle=ref(0);
const budget=()=>{if(!Number.isInteger(cpuMiB.value)||cpuMiB.value<1||cpuMiB.value>4096)throw Error('Native CPU mesh budget must be 1–4096 whole MiB');return {maxTriangles:maxTriangles.value,maxLogicalCpuMeshBytes:cpuMiB.value*1048576};};
const trace=computed(()=>{if(!lastManifest.value)return null;try{return {value:traceNativeTriangle(lastManifest.value,triangle.value)};}catch(error){return {error:error.message};}});
const busy=ref(false),message=ref('');watch([purpose,maxTriangles,cpuMiB],()=>{message.value='';lastManifest.value=null;});
async function fileSelected(event){const file=event.target.files?.[0];event.target.value='';if(!file||busy.value)return;busy.value=true;lastManifest.value=null;try{nativeResourceCheck(1,budget());if(file.size>MAX_SIMULATION_HANDOFF_BYTES)throw Error('Simulation handoff exceeds 8 MiB');const {bytes,manifest}=await nativeViewerZip(await file.text(),{requiredFeatures:required.value,resourceBudget:budget()});if(disposed)return;const url=URL.createObjectURL(new Blob([bytes],{type:'application/zip'})),link=document.createElement('a');link.href=url;link.download='terratec-native-viewer.zip';link.click();lastManifest.value=manifest;triangle.value=0;setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='Native viewer bundle exported: '+manifest.summary.triangles+' triangles. Geometry supported; physical-material execution unsupported.';}catch(error){message.value=error.message;}finally{busy.value=false;}}
</script>
<template><section aria-label="Native viewer adapter"><h4>TerraFlux native viewer adapter</h4><p class="hint">Target: {{ NATIVE_VIEWER_PROFILE.id }} at {{ NATIVE_VIEWER_PROFILE.commit.slice(0,7) }}. Choose a checksummed simulation handoff to download scene.json, OBJ geometry and provenance sidecars in one ZIP. This is native-viewer geometry ingestion; physical materials and live simulation are not executed.</p><label>Native adapter purpose<select v-model="purpose" :disabled="busy" aria-label="Native adapter purpose"><option value="geometry">Geometry viewer</option><option value="physics">Physical simulation</option></select></label><p data-testid="native-capability-status" role="status">{{ capabilities.status }}{{ capabilities.unsupported.length?': '+capabilities.unsupported.join(', '):'' }}</p><p class="hint">Capabilities describe the pinned source profile. Native rendering still needs a runtime smoke check on the receiving graphics setup.</p><label>Native triangle limit<input v-model.number="maxTriangles" :disabled="busy" type="number" min="1" max="2000000" step="1"></label><label>Native logical CPU mesh budget MiB<input v-model.number="cpuMiB" :disabled="busy" type="number" min="1" max="4096" step="1"></label><p class="hint">Export policy only: logical retained mesh bytes exclude parser peak memory, textures, GPU resources and framebuffers. The reviewed native vertex layout is checked by the pinned C++ harness.</p><label>Export native viewer bundle from handoff<input :disabled="busy||capabilities.status!=='supported-by-profile'" type="file" accept=".json,application/json" @change="fileSelected"></label><p data-testid="native-adapter-message" role="status">{{ message }}</p><div v-if="lastManifest"><p data-testid="native-budget-report">{{ lastManifest.resources.usage.logicalCpuMeshBytes }} logical CPU mesh bytes · {{ lastManifest.resources.utilization.logicalCpuMeshPercent }}% of budget · {{ lastManifest.summary.triangles }} triangles</p><label>Native zero-based triangle<input v-model.number="triangle" type="number" min="0" :max="lastManifest.summary.triangles-1" step="1"></label><p data-testid="native-source-trace">{{ trace?.error??JSON.stringify(trace?.value) }}</p><p class="hint">Range lookup uses the just-exported verified model. This does not add picking support to the engine's single mesh node.</p></div></section></template>
